// Emit a browser copy of the block renderer, for the editor's preview pane.
//
// The preview has to be the same renderer the build uses. If it were a second
// implementation it would drift, and a preview that drifts is worse than no
// preview: it tells the client their page looks one way and then publishes
// another. So this concatenates the actual source of frommarkdown.js,
// components.js and torender.js rather than reimplementing them — one
// definition, two places it runs.
//
// All three are plain functions with no Node APIs, so the only things that
// need removing are the module boilerplate at their edges.
const fs = require('fs');
const path = require('path');

const LIB = __dirname;

function stripModuleSyntax(src) {
  return src
    .replace(/^const\s+\{[^}]*\}\s*=\s*require\([^)]*\);?\s*$/gm, '')
    .replace(/^module\.exports\s*=[^;]*;?\s*$/gm, '');
}

function buildPreviewBundle() {
  const md = stripModuleSyntax(fs.readFileSync(path.join(LIB, 'frommarkdown.js'), 'utf8'));
  const components = stripModuleSyntax(fs.readFileSync(path.join(LIB, 'components.js'), 'utf8'));
  const render = stripModuleSyntax(fs.readFileSync(path.join(LIB, 'torender.js'), 'utf8'));

  // components.js reaches its neighbour through `const { fromMarkdown } =
  // require(...)`, and stripping the require takes that binding with it. The
  // function on the other side is called `blocks` and only becomes
  // `fromMarkdown` at the export, so the bridge has to be rebuilt by hand —
  // otherwise every prose block throws at the moment a client opens a page.
  //
  // toMarkdown goes the other way, HTML back into a block, which the preview
  // never does. Rather than ship a parser nothing calls, it is stubbed with
  // something that says so if that assumption ever stops being true.
  const bridge = [
    'const fromMarkdown = blocks;',
    'const toMarkdown = function () {',
    "  throw new Error('toMarkdown is not part of the preview bundle');",
    '};',
  ].join('\n');

  const parts = [md, bridge, components, render];

  return `/* Generated by build/lib/preview-bundle.js — do not edit.
   The block renderer, compiled for the editor's preview pane. Same source as
   the build uses, so what the client sees is what gets published. */
(function () {
  'use strict';
${parts.join('\n')}
  window.metupukRender = { renderBlocks: renderBlocks, fromMarkdown: blocks };
}());
`;
}

module.exports = { buildPreviewBundle };
